import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int THREADS = 256;

__global__ void cute_matvec_kernel(
    const float* A,
    const float* B,
    float* C,
    int M,
    int K)
{
    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(M, K),
        make_stride(K, Int<1>{}));
    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K),
        make_stride(Int<1>{}));
    extern __shared__ float reduction[];
    auto sReduction = make_tensor(
        make_smem_ptr(reduction),
        make_shape(Int<THREADS>{}),
        make_stride(Int<1>{}));
    const int row = static_cast<int>(blockIdx.x);
    const int tid = static_cast<int>(threadIdx.x);
    if (row >= M) {
        return;
    }
    float accum = 0.0f;
    const float* row_a = A + static_cast<std::size_t>(row) * K;
    const bool aligned16 =
        ((reinterpret_cast<std::uintptr_t>(row_a) & 0xF) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(B) & 0xF) == 0);
    if (aligned16) {
        for (int k = tid * 4; k + 3 < K; k += THREADS * 4) {
            const float4 a4 =
                *reinterpret_cast<const float4*>(row_a + k);
            const float4 b4 =
                *reinterpret_cast<const float4*>(B + k);
            accum += a4.x * b4.x;
            accum += a4.y * b4.y;
            accum += a4.z * b4.z;
            accum += a4.w * b4.w;
        }
        if (tid == 0) {
            for (int k = K & ~3; k < K; ++k) {
                accum += row_a[k] * B[k];
            }
        }
    } else {
        for (int k = tid; k < K; k += THREADS) {
            accum += gA(row, k) * gB(k);
        }
    }
    sReduction(tid) = accum;
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            sReduction(tid) += sReduction(tid + offset);
        }
        __syncthreads();
    }
    if (tid == 0) {
        C[row] = sReduction(0);
    }
}


torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must have shape (M, K)");
    TORCH_CHECK(B.dim() == 2, "B must have shape (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const int M = static_cast<int>(A.size(0));
    const int K = static_cast<int>(A.size(1));

    TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");

    auto C = torch::empty({M, 1}, A.options());

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matvec_kernel<<<
        dim3(M),
        dim3(THREADS),
        THREADS * sizeof(float),
        stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE matrix-vector kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)

